// Yonsei University International Campus (연세대 국제캠퍼스, 송도). Data is generated by scripts/campuses/yonseiSongdo/build-package.mjs
// from the pilot (pilot/yonsei-songdo): 24 destructible buildings (13 detailed + 11 generic), a baked ground (flat site with the
// sunken library court, lawn plates, the dorm podium deck, road paint, trees and site furniture) and the non-destructible
// context (Songdo towers, arterial roads, water) that fades into the haze like the pilot preview.
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, YS_PLACEMENTS, YS_BUILDING_BASE, YS_HEIGHT_GRIDS, YS_HEIGHT_RANGE_M, YS_ENV_IDS, YS_GROUND_LOOK, YS_DISPLAY, YS_PROVENANCE } from './data.js';
import { YS_FOOTPRINTS } from './footprints.js?v=tape41';

const MODEL_IDS = Object.freeze(YS_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/yonseiSongdo/${file}`, import.meta.url).href;

export const YONSEI_SONGDO = Object.freeze({
  id: 'yonseiSongdo',
  meta: Object.freeze({ school: '연세대학교', campus: '국제캠퍼스(송도)', short: '연세대 송도', modelNoun: '연세대' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: YS_PLACEMENTS,
  approvedCount: YS_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: Object.freeze(['library', 'veritasA', 'veritasC', 'mainHall', 'libertasA', 'dormD']),
  startBuildingId: 'library',
  // Start from the central lawn side (SE), looking up the library axis with the lecture halls and dorms behind it.
  view: Object.freeze({ startTurn: -0.1 }),
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: YS_ENV_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  terrain: Object.freeze({ heightGrids: YS_HEIGHT_GRIDS, buildingBase: YS_BUILDING_BASE,
    source: 'Flat reclaimed site (Copernicus GLO-30 check) with built levels from photos (pilot/yonsei-songdo); not a survey' }),
  environment: Object.freeze({ provenance: YS_PROVENANCE, sourceNote: 'OSM surroundings (© OpenStreetMap contributors, ODbL); built levels, planting, site furniture and tower heights estimated' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: YS_ENV_IDS, castShadow: Object.freeze([]), look: YS_GROUND_LOOK, fade: Object.freeze({ ...YS_DISPLAY.fade, colour: YS_DISPLAY.haze }), playMargin_m: 30,
      source: 'pilot/yonsei-songdo preview ground + context, baked' }),
  }),
  // Hazard tape around every destructible building (src/engine/hazard-tape.js, user decision 2026-10-18).
  hazardTape: Object.freeze({ footprints: YS_FOOTPRINTS }),
  scene: Object.freeze({
    background: YS_DISPLAY.haze, fog: Object.freeze({ color: YS_DISPLAY.haze, near: 700, far: 2200 }),
    hemisphere: Object.freeze({ sky: '#eef2f4', ground: '#7d8576', intensity: 1.3 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 2.9, position: Object.freeze([-100, 220, 120]), shadowSpan: 185 }),
    floor: Object.freeze({ color: '#c9cbc8', hidden: true, y: YS_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default YONSEI_SONGDO;
